"use client";

import { useState, useCallback, useRef, useEffect } from "react";
import Header from "@/components/Header";
import SearchBar from "@/components/SearchBar";
import Watchlist from "@/components/Watchlist";
import SearchResults from "@/components/SearchResults";
import ChartPanel from "@/components/ChartPanel";
import { TickerSearchResult, ChartTab, Timeframe } from "@/lib/types";

export default function Home() {
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<TickerSearchResult[]>([]);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [isSearching, setIsSearching] = useState(false);
  const [chartTabs, setChartTabs] = useState<ChartTab[]>([]);
  const [activeTab, setActiveTab] = useState<string | null>(null);
  const [isLoadingChart, setIsLoadingChart] = useState(false);

  const searchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastSearchRef = useRef("");

  const searchTickers = useCallback(async (query: string) => {
    if (query.length < 2) return;
    lastSearchRef.current = query;
    setIsSearching(true);
    try {
      const res = await fetch(
        `/api/tickers/search?prefix=${encodeURIComponent(query)}`
      );
      const data = await res.json();
      if (lastSearchRef.current === query) {
        setSearchResults(data);
      }
    } catch {
      console.error("Search failed");
    } finally {
      setIsSearching(false);
    }
  }, []);

  const handleSearchChange = useCallback(
    (value: string) => {
      setSearchQuery(value);

      if (value.length >= 1) {
        setShowSearchResults(true);
      } else {
        setShowSearchResults(false);
        setSearchResults([]);
      }

      if (searchTimerRef.current) {
        clearTimeout(searchTimerRef.current);
      }

      if (value.length >= 2) {
        searchTimerRef.current = setTimeout(() => {
          searchTickers(value);
        }, 700);
      } else {
        setSearchResults([]);
      }
    },
    [searchTickers]
  );

  useEffect(() => {
    return () => {
      if (searchTimerRef.current) {
        clearTimeout(searchTimerRef.current);
      }
    };
  }, []);

  const handleSearchResultSelect = useCallback(
    async (result: TickerSearchResult) => {
      setIsLoadingChart(true);
      setShowSearchResults(false);
      setSearchQuery("");

      const existingTab = chartTabs.find((t) => t.ticker === result.ticker);
      if (existingTab) {
        setActiveTab(result.ticker);
        setIsLoadingChart(false);
        return;
      }

      const now = new Date();
      const sixMonthsAgo = new Date(now);
      sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);

      const formatDate = (d: Date) => d.toISOString().split("T")[0];

      try {
        const res = await fetch("/api/signals", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            ticker: result.ticker,
            from: formatDate(sixMonthsAgo),
            to: formatDate(now),
          }),
        });

        const data = await res.json();

        const candles = data.candles || [];
        const lastPrice =
          candles.length > 0 ? candles[candles.length - 1].close : 0;

        const newTab: ChartTab = {
          ticker: result.ticker,
          name: result.name || result.ticker,
          data: candles,
          lastPrice,
          timeframe: "DAY",
        };

        setChartTabs((prev) => {
          const existing = prev.find((t) => t.ticker === result.ticker);
          if (existing) return prev;
          return [...prev, newTab];
        });
        setActiveTab(result.ticker);
      } catch {
        console.error("Failed to fetch chart data");
      } finally {
        setIsLoadingChart(false);
      }
    },
    [chartTabs]
  );

  const handleTimeframeChange = useCallback(
    async (ticker: string, timeframe: Timeframe) => {
      const tab = chartTabs.find((t) => t.ticker === ticker);
      if (!tab) return;

      setChartTabs((prev) =>
        prev.map((t) =>
          t.ticker === ticker ? { ...t, timeframe, data: [] } : t
        )
      );

      const now = new Date();
      const from = new Date(now);
      from.setMonth(from.getMonth() - 6);

      const formatDate = (d: Date) => d.toISOString().split("T")[0];

      try {
        const res = await fetch("/api/signals", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            ticker,
            from: formatDate(from),
            to: formatDate(now),
            timeframe,
          }),
        });

        const data = await res.json();
        const candles = data.candles || [];
        const lastPrice =
          candles.length > 0 ? candles[candles.length - 1].close : 0;

        setChartTabs((prev) =>
          prev.map((t) =>
            t.ticker === ticker
              ? { ...t, data: candles, lastPrice, timeframe }
              : t
          )
        );
      } catch {
        console.error("Failed to fetch chart data for timeframe change");
      }
    },
    [chartTabs]
  );

  const handleWatchlistSelect = useCallback((ticker: string) => {
    setActiveTab(ticker);
  }, []);

  const handleCloseSearch = useCallback(() => {
    setShowSearchResults(false);
    setSearchQuery("");
    setSearchResults([]);
  }, []);

  return (
    <div
      style={{
        height: "100vh",
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
      }}
    >
      <Header />
      <div style={{ flex: 1, display: "flex", overflow: "hidden" }}>
        {/* Sidebar */}
        <aside
          style={{
            width: "var(--sidebar-width)",
            borderRight: "1px solid var(--color-border)",
            display: "flex",
            flexDirection: "column",
            flexShrink: 0,
            overflow: "hidden",
          }}
        >
          <SearchBar
            value={searchQuery}
            onChange={handleSearchChange}
            onFocus={() => {
              if (searchQuery.length >= 1) setShowSearchResults(true);
            }}
          />
          <Watchlist items={chartTabs} onSelect={handleWatchlistSelect} />
        </aside>

        {/* Search Results Panel */}
        {showSearchResults && (
          <SearchResults
            results={searchResults}
            searchQuery={searchQuery}
            isLoading={isSearching}
            showTypeMore={searchQuery.length === 1}
            onSelect={handleSearchResultSelect}
            onClose={handleCloseSearch}
          />
        )}

        {/* Main Chart Panel */}
        <main
          style={{
            flex: 1,
            display: "flex",
            flexDirection: "column",
            overflow: "hidden",
            background: "var(--color-bg)",
          }}
        >
          {isLoadingChart ? (
            <div
              style={{
                flex: 1,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: "var(--color-text-muted)",
              }}
            >
              Loading chart data...
            </div>
          ) : (
            <ChartPanel
              tabs={chartTabs}
              activeTab={activeTab}
              onTabSelect={setActiveTab}
              onTimeframeChange={handleTimeframeChange}
            />
          )}
        </main>
      </div>
    </div>
  );
}
