"use client";

import { ChartTab } from "@/lib/types";
import CandlestickChart from "./CandlestickChart";

interface ChartPanelProps {
  tabs: ChartTab[];
  activeTab: string | null;
  onTabSelect: (ticker: string) => void;
}

export default function ChartPanel({
  tabs,
  activeTab,
  onTabSelect,
}: ChartPanelProps) {
  const activeChart = tabs.find((t) => t.ticker === activeTab);

  if (!activeChart) {
    return (
      <div
        style={{
          flex: 1,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "var(--color-text-muted)",
          fontSize: "var(--body-1-size)",
        }}
      >
        Search for a ticker to view its chart
      </div>
    );
  }

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}>
      {/* Ticker Tabs */}
      <div
        style={{
          height: "48px",
          borderBottom: "1px solid var(--color-border)",
          display: "flex",
          alignItems: "center",
          padding: "0 var(--inset-s)",
          gap: 0,
          background: "var(--color-bg-secondary)",
        }}
      >
        {tabs.map((tab) => (
          <button
            key={tab.ticker}
            onClick={() => onTabSelect(tab.ticker)}
            style={{
              padding: "var(--inset-xs) var(--inset-s)",
              border: "none",
              borderBottom:
                tab.ticker === activeTab
                  ? "2px solid var(--color-primary)"
                  : "2px solid transparent",
              background: "transparent",
              cursor: "pointer",
              fontWeight: tab.ticker === activeTab ? 600 : 400,
              fontSize: "var(--body-1-size)",
              color:
                tab.ticker === activeTab
                  ? "var(--color-primary)"
                  : "var(--color-text-secondary)",
              transition: "color 0.15s, border-color 0.15s",
              marginBottom: "-1px",
            }}
          >
            {tab.ticker}
          </button>
        ))}
      </div>

      {/* Chart Header */}
      <div
        style={{
          padding: "var(--inset-s) var(--inset-m)",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          borderBottom: "1px solid var(--color-border-light)",
        }}
      >
        <div>
          <div className="heading-2">{activeChart.name}</div>
          <div
            className="body-1"
            style={{ color: "var(--color-text-muted)", marginTop: "2px" }}
          >
            {activeChart.ticker} &bull; $
            {activeChart.lastPrice.toLocaleString(undefined, {
              minimumFractionDigits: 2,
              maximumFractionDigits: 2,
            })}
          </div>
        </div>

        <div style={{ display: "flex", gap: "var(--space-s)", alignItems: "center" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "var(--space-xs)" }}>
            <span className="body-1" style={{ color: "var(--color-text-secondary)" }}>
              Timeframe:
            </span>
            <div
              style={{
                padding: "var(--inset-xs) 12px",
                border: "1px solid var(--color-border)",
                borderRadius: "var(--radius-m)",
                fontSize: "var(--body-1-size)",
                color: "var(--color-text-primary)",
                background: "var(--color-bg)",
                display: "flex",
                alignItems: "center",
                gap: "var(--space-xs)",
                cursor: "default",
              }}
            >
              1 Day
              <svg
                width="16"
                height="16"
                viewBox="0 0 24 24"
                fill="none"
                stroke="var(--color-text-muted)"
                strokeWidth="2"
              >
                <polyline points="6 9 12 15 18 9" />
              </svg>
            </div>
          </div>

          <div style={{ display: "flex", alignItems: "center", gap: "var(--space-xs)" }}>
            <span className="body-1" style={{ color: "var(--color-text-secondary)" }}>
              Signals:
            </span>
            <div
              style={{
                padding: "var(--inset-xs) 12px",
                border: "1px solid var(--color-border)",
                borderRadius: "var(--radius-m)",
                fontSize: "var(--body-1-size)",
                color: "var(--color-text-primary)",
                background: "var(--color-bg)",
                display: "flex",
                alignItems: "center",
                gap: "var(--space-xs)",
                cursor: "default",
              }}
            >
              All Signals
              <svg
                width="16"
                height="16"
                viewBox="0 0 24 24"
                fill="none"
                stroke="var(--color-text-muted)"
                strokeWidth="2"
              >
                <polyline points="6 9 12 15 18 9" />
              </svg>
            </div>
          </div>
        </div>
      </div>

      {/* Chart */}
      <div style={{ flex: 1, padding: "var(--inset-m)", minHeight: 0 }}>
        <CandlestickChart data={activeChart.data} />
      </div>
    </div>
  );
}
