"use client";

import { ChartTab } from "@/lib/types";

interface WatchlistProps {
  items: ChartTab[];
  onSelect: (ticker: string) => void;
}

export default function Watchlist({ items, onSelect }: WatchlistProps) {
  return (
    <div style={{ flex: 1, overflow: "auto" }}>
      <div
        style={{
          padding: "var(--inset-s)",
          borderBottom: "1px solid var(--color-border)",
        }}
      >
        <span className="heading-3">Watchlist</span>
      </div>
      <div>
        {items.length === 0 && (
          <div
            style={{
              padding: "var(--inset-l) var(--inset-s)",
              textAlign: "center",
              color: "var(--color-text-muted)",
              fontSize: "var(--body-2-size)",
            }}
          >
            No tickers in watchlist. Search and select a ticker to get started.
          </div>
        )}
        {items.map((item) => {
          const changePercent =
            item.data.length > 1
              ? (
                  ((item.data[item.data.length - 1].close -
                    item.data[0].open) /
                    item.data[0].open) *
                  100
                ).toFixed(2)
              : "0.00";
          const isPositive = parseFloat(changePercent) >= 0;

          return (
            <button
              key={item.ticker}
              onClick={() => onSelect(item.ticker)}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                width: "100%",
                padding: "12px var(--inset-s)",
                margin: "0 var(--inset-xs)",
                marginRight: "var(--inset-xs)",
                background: "transparent",
                border: "none",
                borderRadius: "var(--radius-m)",
                cursor: "pointer",
                textAlign: "left",
                transition: "background 0.15s",
              }}
              onMouseEnter={(e) =>
                (e.currentTarget.style.background =
                  "var(--color-bg-secondary)")
              }
              onMouseLeave={(e) =>
                (e.currentTarget.style.background = "transparent")
              }
            >
              <div>
                <div
                  style={{
                    fontWeight: 600,
                    fontSize: "var(--body-1-size)",
                    color: "var(--color-text-primary)",
                  }}
                >
                  {item.ticker}
                </div>
                <div
                  className="body-2"
                  style={{ color: "var(--color-text-muted)" }}
                >
                  {item.name}
                </div>
              </div>
              <div style={{ textAlign: "right" }}>
                <div
                  style={{
                    fontWeight: 600,
                    fontSize: "var(--body-1-size)",
                  }}
                >
                  ${item.lastPrice.toLocaleString(undefined, {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2,
                  })}
                </div>
                <div
                  className="body-2"
                  style={{
                    color: isPositive
                      ? "var(--color-positive)"
                      : "var(--color-negative)",
                  }}
                >
                  {isPositive ? "+" : ""}
                  {changePercent}%
                </div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}
